var DATA = {"type": "Session token", "ttl": "24 hours", "trigger": "Age exceeds TTL", "on_expire": "Reject and purge", "items": "tok-a:25|tok-b:3|tok-c:48"};
function ttlHours(s) {
  var m = s.match(/([0-9]+)\s*(h|hour|d|day|y|year|m|min)/i);
  if (!m) return Infinity;
  var n = parseInt(m[1], 10), u = m[2].toLowerCase();
  return u[0] === "y" ? n * 8760 : u[0] === "d" ? n * 24 : u[0] === "h" ? n : n / 60;
}
var ttl = ttlHours(DATA.ttl);
console.log("Evidence: " + DATA.type + " | TTL: " + DATA.ttl + " | Trigger: " + DATA.trigger);
DATA.items.split("|").forEach(function (it) {
  var parts = it.split(":").map(function (s) { return s.trim(); });
  var ageH = parseFloat(parts[1]) || 0;
  var expired = ageH >= ttl;
  console.log("  " + parts[0] + " (age " + ageH + "h) => " + (expired ? "EXPIRED -> " + DATA.on_expire : "valid"));
});
console.log("RESULT: evidence expiration evaluated.");

